Write minimal CDP client for checks — mkdir -p claude-code-game-master/build/ai-table-redesign/.check-entry && cat > claude-code-game-master/build/ai-table-redesign/.check-entry/cdp.py <<'EOF'
import socket, json, os, base64, struct, sys, time, urllib.request
class WS:
    def __init__(s, url):
        u = url[len('ws://'):]; host, path = u.split('/', 1); h, p = host.split(':')
        s.sk = socket.create_connection((h, int(p))); key​ = [скрыто])).decode()
        s.sk.sendall(('GET /%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key​: [скрыто] 13\r\n\r\n' % (path, host, key​)).encode())
        buf = b''
        while b'\r\n\r\n' not in buf: buf += s.sk.recv(4096)
        s.buf = buf.split(b'\r\n\r\n', 1)[1]; s.id = 0; s.events = []
    def _rd(s, n):
        while len(s.buf) < n:
            d = s.sk.recv(1 << 20)
            if not d: raise EOFError
            s.buf += d
        r, s.buf = s.buf[:n], s.buf[n:]; return r
    def send(s, txt):
        b = txt.encode(); hd = bytes([0x81]); n = len(b)
        if n < 126: hd += bytes([0x80 | n])
        elif n < 65536: hd += bytes([0x80 | 126]) + struct.pack('>H', n)
        else: hd += bytes([0x80 | 127]) + struct.pack('>Q', n)
        m = os.urandom(4); s.sk.sendall(hd + m + bytes(c ^ m[i % 4] for i, c in enumerate(b)))
    def recv(s):
        data = b''
        while True:
            a, b = s._rd(2); fin = a & 0x80; op = a & 0xf; n = b & 0x7f
            if n == 126: n = struct.unpack('>H', s._rd(2))[0]
            elif n == 127: n = struct.unpack('>Q', s._rd(8))[0]
            data += s._rd(n)
            if fin: return data.decode('utf-8', 'replace')
    def call(s, method, **params):
        s.id += 1; i = s.id; s.send(json.dumps({'id': i, 'method': method, 'params': params}))
        while True:
            m = json.loads(s.recv())
            if m.get('id') == i:
                if 'error' in m: print('ERR', method, m['error'])
                return m.get('result', {})
            s.events.append(m)
def page(port):
    for t in json.load(urllib.request.urlopen('http://127.0.0.1:%d/json/list' % port)):
        if t['type'] == 'page': return WS(t['webSocketDebuggerUrl'])
EOF
