P.call('Emulation.setDeviceMetricsOverride', width=1920, height=1080, deviceScaleFactor=1, mobile=False)
OUT = sys.argv[1]
def ev(expr):
    r = P.call('Runtime.evaluate', expression=expr, awaitPromise=True, returnByValue=True)
    if 'exceptionDetails' in r: print('EXC', r['exceptionDetails'].get('exception', {}).get('description', r['exceptionDetails']))
    return r.get('result', {}).get('value')
