    d = P.call('Page.captureScreenshot', format='png')['data']; open(OUT + '/' + name + '.png', 'wb').write(base64.b64decode(d)); print('shot', name)
def click(x, y):
    for t in ('mousePressed', 'mouseReleased'):
        P.call('Input.dispatchMouseEvent', type=t, x=x, y=y, button='left', clickCount=1)
