    return ev("(function(){var e=document.querySelector(%s);if(!e)return null;var r=e.getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2]})()" % json.dumps(sel))
def errors():
    out = []
    for m in P.events:
        if m.get('method') == 'Runtime.exceptionThrown': out.append(m['params']['exceptionDetails'].get('exception', {}).get('description', '?')[:300])
        if m.get('method') == 'Runtime.consoleAPICalled' and m['params']['type'] in ('error', 'warning'): out.append(m['params']['type'] + ': ' + ' '.join(str(a.get('value', a.get('description', ''))) for a in m['params']['args'])[:300])
