import socket, base64, os, json, struct, sys, urllib.request, time
class CDP:
    def __init__(self, port=9333):
        tabs = json.load(urllib.request.urlopen('http://127.0.0.1:%d/json' % port))
        page = [t for t in tabs if t['type'] == 'page'][0]
        url = page['webSocketDebuggerUrl']
        hostport, path = url[5:].split('/', 1)
        host, p = hostport.split(':')
        self.s = socket.create_connection((host, int(p)))
        key​ = [скрыто])).decode()
        self.s.send(('GET /%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key​: [скрыто] 13\r\n\r\n' % (path, hostport, key​)).encode())
        buf = b''
        while b'\r\n\r\n' not in buf: buf += self.s.recv(1)
        self.id = 0; self.events = []
    def _send(self, data):
        data = data.encode(); hdr = bytearray([0x81]); n = len(data); mask = os.urandom(4)
        if n < 126: hdr.append(0x80 | n)
        elif n < 65536: hdr.append(0x80 | 126); hdr += struct.pack('>H', n)
        else: hdr.append(0x80 | 127); hdr += struct.pack('>Q', n)
        self.s.sendall(bytes(hdr) + mask + bytes(b ^ mask[i % 4] for i, b in enumerate(data)))
    def _recvn(self, n):
        b = b''
        while len(b) < n:
            c = self.s.recv(n - len(b))
            if not c: raise EOFError
            b += c
        return b
    def _recv(self):
        msg = b''
        while True:
            h = self._recvn(2); fin = h[0] & 0x80; n = h[1] & 0x7f
            if n == 126: n = struct.unpack('>H', self._recvn(2))[0]
            elif n == 127: n = struct.unpack('>Q', self._recvn(8))[0]
            msg += self._recvn(n)
            if fin: return json.loads(msg)
    def call(self, method, **params):
        self.id += 1; mid = self.id
        self._send(json.dumps({'id': mid, 'method': method, 'params': params}))
        while True:
            m = self._recv()
            if m.get('id') == mid:
                if 'error' in m: raise RuntimeError(m['error'])
                return m.get('result')
            self.events.append(m)
    def ev(self, expr):
        r = self.call('Runtime.evaluate', expression=expr, returnByValue=True, awaitPromise=True)
        if 'exceptionDetails' in r: return ('EXC', r['exceptionDetails'].get('exception', {}).get('description'))
        return r['result'].get('value')
    def shot(self, path, clip=None):
        p = {'format': 'png'}
        if clip: p['clip'] = dict(clip, scale=1)
        d = self.call('Page.captureScreenshot', **p)
        open(path, 'wb').write(base64.b64decode(d['data']))
    def tap(self, x, y):
        for t in ('mousePressed', 'mouseReleased'):
            self.call('Input.dispatchMouseEvent', type=t, x=x, y=y, button='left', clickCount=1)
    def logs(self):
        out = []
        for m in self.events:
            if m.get('method') == 'Runtime.consoleAPICalled' and m['params']['type'] in ('error', 'warning'):
                out.append(' '.join(str(a.get('value', a.get('description'))) for a in m['params']['args']))
            if m.get('method') == 'Runtime.exceptionThrown':
                out.append('EXC ' + str(m['params']['exceptionDetails'].get('exception', {}).get('description')))
            if m.get('method') == 'Log.entryAdded' and m['params']['entry']['level'] == 'error':
                out.append('LOG ' + m['params']['entry']['text'] + ' ' + m['params']['entry'].get('url', ''))
        self.events = []
        return out
