import socket,base64,os,json,struct,urllib.request,sys,time
class WS:
    def __init__(s,url):
        h=url.split('/')[2]; host,port=h.split(':'); path='/'+url.split('/',3)[3]
        s.s=socket.create_connection((host,int(port)))
        k=base64.b64encode(os.urandom(16)).decode()
        s.s.send(f"GET {path} HTTP/1.1\r\nHost: {h}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key​: {k}\r\nSec-WebSocket-Version: 13\r\n\r\n".encode())
        b=b''
        while b'\r\n\r\n' not in b: b+=s.s.recv(1)
        s.id=0; s.events=[]
    def send(s,d):
        p=json.dumps(d).encode(); hd=bytes([0x81]); n=len(p)
        hd+= bytes([0x80|n]) if n<126 else (bytes([0x80|126])+struct.pack('>H',n) if n<65536 else bytes([0x80|127])+struct.pack('>Q',n))
        m=os.urandom(4); s.s.send(hd+m+bytes(c^m[i%4] for i,c in enumerate(p)))
    def rx(s,n):
        b=b''
        while len(b)<n:
            c=s.s.recv(n-len(b))
            if not c: raise EOFError
            b+=c
        return b
    def recv(s):
        msg=b''
        while True:
            h=s.rx(2); fin=h[0]&0x80; n=h[1]&0x7f
            if n==126: n=struct.unpack('>H',s.rx(2))[0]
            elif n==127: n=struct.unpack('>Q',s.rx(8))[0]
            msg+=s.rx(n)
            if fin: return json.loads(msg)
    def call(s,method,**params):
        s.id+=1; i=s.id; s.send({'id':i,'method':method,'params':params})
        while True:
            m=s.recv()
            if m.get('id')==i: return m.get('result',m.get('error'))
            s.events.append(m)
    def pump(s,t):
        s.s.settimeout(t)
        try:
            while True: s.events.append(s.recv())
        except Exception: pass
        s.s.settimeout(None)
def connect(port):
    tabs=json.load(urllib.request.urlopen(f'http://127.0.0.1:{port}/json'))
    t=[x for x in tabs if x['type']=='page'][0]
    return WS(t['webSocketDebuggerUrl'])
