import sys,json,time,base64
from cdp import connect
w=connect(9561)
for d in ['Runtime','Log','Network','Page']: w.call(d+'.enable')
def ev(js):
    r=w.call('Runtime.evaluate',expression=js,returnByValue=True,awaitPromise=True)
    return r.get('result',{}).get('value', r)
def shot(name):
    r=w.call('Page.captureScreenshot',format='jpeg',quality=60)
    open(name+'.jpg','wb').write(base64.b64decode(r['data']))
def drain(t):
    w.pump(t); out=[]
    for m in w.events:
        me=m.get('method')
        if me=='Runtime.exceptionThrown':
            e=m['params']['exceptionDetails']; out.append('EXC '+(e.get('exception',{}).get('description') or e.get('text'))[:300])
        elif me=='Runtime.consoleAPICalled' and m['params']['type'] in ('error','warning'):
            out.append('CON '+m['params']['type']+' '+' '.join(str(a.get('value',a.get('description','')))[:200] for a in m['params']['args']))
        elif me=='Network.responseReceived' and m['params']['response']['status']>=400:
            out.append('HTTP %d %s'%(m['params']['response']['status'],m['params']['response']['url']))
        elif me=='Network.loadingFailed' and not m['params'].get('canceled'):
            out.append('NETFAIL '+m['params'].get('errorText',''))
    w.events.clear(); return out
PROBE=open('probe.js').read()
w.call('Emulation.setDeviceMetricsOverride',width=int(sys.argv[1]),height=int(sys.argv[2]),deviceScaleFactor=1,mobile=False)
