    ev("location.hash='%s'"%spec); time.sleep(2.5)
    errs=drain(1.5)
    p=ev(PROBE)
    print(spec, json.dumps(errs,ensure_ascii=False), json.dumps(p,ensure_ascii=False))
    shot('s'+spec.replace('/','_'))
